code_sketch:
enum Suit: String, CaseIterable {
    case clubs, diamonds, hearts, spades
}

Suit(rawValue: "clubs")     // Suit? - failable at the boundary
Suit.clubs.rawValue         // "clubs"

switch Suit.clubs {         // exhaustive: no default arm
case .clubs: break; case .diamonds: break
case .hearts: break; case .spades: break
}
